import { _decorator, Component, RigidBody, Node, Vec3 } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('PanShake')
export class PanShake extends Component {
    // 锅内小球父节点
    @property(Node)
    ballParent: Node = null!;
    // 向上抛力
    @property
    jumpForce: number = 5;
    // 水平随机偏移力度
    @property
    horizontalForce: number = 1;
    // 空中旋转扭矩大小
    @property
    rotateTorque: number = 3;
    // 点击冷却时间
    @property
    coolDownTime: number = 0.4;

    private coolDownTimer: number = 0;

    update(delta: number) {
        if (this.coolDownTimer > 0) this.coolDownTimer -= delta;
    }

    onPanShakeBtnClick() {
        // 冷却拦截，防止连点叠加冲量
        if (this.coolDownTimer > 0 || !this.ballParent) return;
        this.coolDownTimer = this.coolDownTime;

        for (const child of this.ballParent.children) {
            const rigid = child.getComponent(RigidBody);
            if (!rigid) continue;

            // 1. 施加向上抛的线性冲量
            const randX = (Math.random() - 0.5) * this.horizontalForce;
            const randZ = (Math.random() - 0.5) * this.horizontalForce;
            const impulse = new Vec3(randX, this.jumpForce, randZ);
            rigid.applyImpulse(impulse);

            // 2. 施加随机旋转扭矩，升空自带翻滚
            const torque = new Vec3(
                (Math.random() - 0.5) * this.rotateTorque,
                (Math.random() - 0.5) * this.rotateTorque * 0.5,
                (Math.random() - 0.5) * this.rotateTorque
            );
            rigid.applyTorque(torque);
        }
    }
}